def transform(grid):
    h, w = len(grid), len(grid[0])
    freq = {}
    for row in grid:
        for x in row:
            freq[x] = freq.get(x, 0) + 1

    # The separator is the uniform row whose color is least frequent overall.
    sep = min(
        (i for i, row in enumerate(grid) if len(set(row)) == 1),
        key=lambda i: freq[grid[i][0]]
    )
    upper, lower = grid[:sep], grid[sep + 1:]

    upper_colors = {x for row in upper for x in row}
    lower_colors = {x for row in lower for x in row}
    shared = upper_colors & lower_colors
    mismatch = max(shared, key=lambda c: sum(row.count(c) for row in lower))

    return [
        [3 if a == b else mismatch for a, b in zip(ra, rb)]
        for ra, rb in zip(upper, lower)
    ]
